//ENGINE-START
function combosFor(G,card){
  const res=[];
  COMBOS.forEach((cb,i)=>{
    if(G.fired.has(i))return;
    const a=cb.p[0],b=cb.p[1],hasA=card.tags.indexOf(a)>=0,hasB=card.tags.indexOf(b)>=0;
    let partner=null;
    if(a===b){if(hasA&&(G.owners[a]||[]).length)partner=G.owners[a];}
    else if(hasA&&(G.owners[b]||[]).length)partner=G.owners[b];
    else if(hasB&&(G.owners[a]||[]).length)partner=G.owners[a];
    if(partner)res.push({i:i,cb:cb,partner:partner});
  });
  return res;
}
function futureHas(tag,fromStep){
  for(let s=fromStep;s<NODES.length;s++)if(NODES[s].pool.some(c=>c.tags.indexOf(tag)>=0))return true;
  return false;
}
function openThreads(G,tags,fromStep){
  const seen={};let n=0;
  COMBOS.forEach((cb,i)=>{
    if(G.fired.has(i)||seen[i])return;
    for(let k=0;k<tags.length;k++){
      const t=tags[k];if(cb.p.indexOf(t)<0)continue;
      const other=cb.p[0]===t?cb.p[1]:cb.p[0];
      if(futureHas(other,fromStep)){seen[i]=1;n++;break;}
    }
  });
  return n;
}

// Deterministic scoring from the picks. The game and the leaderboard Worker both call this,
// so a submitted run can be re-checked on the server. Returns null for an illegal run.
function scoreRun(probIdx,picks,luck){
  const prob=PROBLEMS[probIdx];
  if(!prob||!Array.isArray(picks)||picks.length!==NODES.length)return null;
  const G={r:START.r,v:START.v,t:START.t,spent:0,owners:{},fired:new Set()};
  let noise=5;
  for(let s=0;s<NODES.length;s++){
    if(!Number.isInteger(picks[s]))return null;
    const c=NODES[s].pool[picks[s]];if(!c)return null;
    const fx=Object.assign({r:0,v:0,t:0,c:0},c.fx);
    combosFor(G,c).forEach(h=>{['r','v','t'].forEach(k=>{fx[k]+=(h.cb.fx[k]||0);});G.fired.add(h.i);});
    G.r+=fx.r;G.v+=fx.v;G.t+=fx.t;G.spent+=fx.c;
    c.tags.forEach(t=>{(G.owners[t]=G.owners[t]||[]).push(s);});
    if(c.noise!==undefined)noise=c.noise;
  }
  const L={r:0,v:0,t:0};
  if(!luck)return null;
  for(const k of ['r','v','t']){const x=luck[k];if(!Number.isInteger(x)||Math.abs(x)>noise)return null;L[k]=x;}
  const clamp=v=>Math.max(0,Math.min(100,v));
  const over=Math.max(0,G.spent-BUDGET), f={};
  ['r','v','t'].forEach(k=>{f[k]=clamp(G[k]+L[k]-over*0.8);});
  const goals=Object.keys(prob.goal), hit=goals.filter(k=>f[k]>=prob.goal[k]);
  const won=hit.length===goals.length;
  const avg=(f.r+f.v+f.t)/3;
  const score=Math.round(Math.min(100,avg*0.6+(hit.length/goals.length)*40));
  const grade=score>=88?'S':score>=76?'A':score>=62?'B':score>=48?'C':'D';
  const whaleDep=COMBOS.findIndex(c=>c.p[0]==='whale'&&c.p[1]==='whale');
  let arch='The Generalist';
  if(over>0)arch='The Scope Creeper';
  else if(G.fired.has(whaleDep))arch='The Whale Hunter';
  else if(G.fired.size>=4&&won)arch='The Connector';
  else if(f.v>=70&&f.t>=55)arch='The Systems Architect';
  else if(f.r>=75)arch='The Retention Engineer';
  else if(f.t>=70&&f.v<55)arch='The Player Advocate';
  else if(G.owners.tested&&f.r>=55&&f.v>=55&&f.t>=55)arch='The Disciplined Shipper';
  return {f:f,won:won,score:score,grade:grade,arch:arch,over:over,combos:G.fired.size,noise:noise,spent:G.spent};
}
//ENGINE-END

export { scoreRun, combosFor, PROBLEMS, NODES, COMBOS, START, BUDGET };
